"""
write_templates.py - Decode and write all HTML templates during Docker build.
Run: python write_templates.py
Each template is gzip-compressed and base64-encoded to survive GitHub pasting.
"""
import gzip, base64, os

TEMPLATES = {
    "templates/admin/base_admin.html": "",
    "templates/admin/booking_detail.html": "",
    "templates/admin/bookings.html": "",
    "templates/admin/dashboard.html": "",
    "templates/admin/guide_form.html": "",
    "templates/admin/guides.html": "",
    "templates/admin/login.html": "",
    "templates/admin/message_detail.html": "",
    "templates/admin/messages.html": "",
    "templates/admin/reports.html": "",
    "templates/admin/scooter_form.html": "",
    "templates/admin/scooters.html": "",
    "templates/admin/settings.html": "",
    "templates/admin/slots.html": "",
    "templates/admin/tour_form.html": "",
    "templates/admin/tours.html": "",
    "templates/admin/waiver_form.html": "",
    "templates/admin/waivers.html": "",
    "templates/base.html": "",
    "templates/emails/booking_confirmation.html": "",
    "templates/public/about.html": "",
    "templates/public/book.html": "",
    "templates/public/booking_detail.html": "",
    "templates/public/booking_lookup.html": "",
    "templates/public/booking_success.html": "",
    "templates/public/index.html": "",
    "templates/public/payment.html": "",
    "templates/public/tour_detail.html": "",
    "templates/public/waiver.html": "",
    "templates/public/widget.html": "",
}

for path, data in TEMPLATES.items():
    os.makedirs(os.path.dirname(path), exist_ok=True)
    content = gzip.decompress(base64.b64decode(data))
    with open(path, "wb") as f:
        f.write(content)
    print(f"  Wrote {path} ({len(content)} bytes)")

print(f"Done! {len(TEMPLATES)} templates written.")
